      sym:n?s;
      side:n?"BS";
      price:((+;-)side="B") .'flip(dict sym;.05*n?1+til 10);
      sample:flip`time`sym`side`price`size!
        (09:30:00+til n;sym;side;price;100*n?1+til 10) }

    x:create 10

/sample upd functions to populate each structure
